    public static void solve(DataReader dr, PrintWriter out) {
        int n = dr.nextInt();
        int k = dr.nextInt();

        String s = dr.nextToken();

        boolean[] used = new boolean[n];

        class DFS {
            boolean dfs(int u) {
                if (u < 0 || u >= n || used[u] || s.charAt(u) == '#') return false;
                if (s.charAt(u) == 'T') return true;
                used[u] = true;

                return dfs(u - k) || dfs(u + k);
            }
        }

